//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient errors, which may be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("blip".to_string()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("bad input".to_string()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for every retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a new configuration.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Delay to wait before the retry at 0-based `retry_index`
    /// (0 = before the first retry), i.e. `min(base * 2^retry_index, max)`.
    ///
    /// Uses saturating arithmetic: once the doubling exponent exceeds the
    /// safe range for `u64`, the delay clamps to `max_delay_ms` instead of
    /// overflowing.
    pub(crate) fn delay_before_retry(&self, retry_index: u32) -> u64 {
        // 2^64 does not fit in u64, so any exponent >= 64 saturates.
        let exponent = retry_index.min(64);
        let factor = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(factor)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_retry_delay_is_base_delay() {
        let cfg = RetryConfig::new(3, 10, 1_000);
        assert_eq!(cfg.delay_before_retry(0), 10);
    }

    #[test]
    fn delay_doubles_exponentially() {
        let cfg = RetryConfig::new(10, 10, 10_000);
        assert_eq!(cfg.delay_before_retry(0), 10);
        assert_eq!(cfg.delay_before_retry(1), 20);
        assert_eq!(cfg.delay_before_retry(2), 40);
        assert_eq!(cfg.delay_before_retry(3), 80);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let cfg = RetryConfig::new(10, 10, 100);
        assert_eq!(cfg.delay_before_retry(3), 80);
        assert_eq!(cfg.delay_before_retry(4), 100);
        assert_eq!(cfg.delay_before_retry(5), 100);
        assert_eq!(cfg.delay_before_retry(100), 100);
    }

    #[test]
    fn attempts_above_safe_exponent_saturate_without_overflow() {
        // 2^63 is the largest power of two representable in u64.
        let cfg = RetryConfig::new(100, 1, u64::MAX);
        assert_eq!(cfg.delay_before_retry(62), 1u64 << 62);
        assert_eq!(cfg.delay_before_retry(63), 1u64 << 63);
        // 2^64 would overflow; the delay must saturate at max_delay_ms.
        assert_eq!(cfg.delay_before_retry(64), u64::MAX);
        assert_eq!(cfg.delay_before_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn base_delay_above_max_is_capped() {
        let cfg = RetryConfig::new(3, 500, 100);
        assert_eq!(cfg.delay_before_retry(0), 100);
        assert_eq!(cfg.delay_before_retry(5), 100);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Transient errors are retried with an exponential backoff bounded by
/// `RetryConfig::max_delay_ms`; permanent errors return immediately.
/// `max_attempts` includes the first call.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut remaining = max_attempts;
    let mut retry_index = 0u32;
    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if err.is_transient() && remaining > 1 => {
                sleeper.sleep_ms(config.delay_before_retry(retry_index));
                remaining -= 1;
                retry_index += 1;
            }
            Err(err) => return Err(err),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn transient(msg: &str) -> RetryError {
        RetryError::Transient(msg.to_string())
    }

    fn permanent(msg: &str) -> RetryError {
        RetryError::Permanent(msg.to_string())
    }

    #[test]
    fn success_on_first_call_never_sleeps() {
        let cfg = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Ok(())
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_returns_immediately() {
        let cfg = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Err(permanent("nope"))
        });
        assert_eq!(result, Err(permanent("nope")));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn transient_error_is_retried_until_success() {
        let cfg = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(transient("blip"))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let cfg = RetryConfig::new(3, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&cfg, &mut sleeper, || {
            calls += 1;
            Err(transient("always"))
        });
        assert_eq!(result, Err(transient("always")));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn single_attempt_never_sleeps() {
        let cfg = RetryConfig::new(1, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&cfg, &mut sleeper, || Err(transient("blip")));
        assert_eq!(result, Err(transient("blip")));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delays_saturate_at_max_delay() {
        let cfg = RetryConfig::new(8, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let _ = run_job(&cfg, &mut sleeper, || Err(transient("always")));
        assert_eq!(sleeper.sleeps, vec![10, 20, 40, 80, 100, 100, 100]);
    }

    #[test]
    fn large_delays_above_safe_exponent_saturate_without_overflow() {
        // 2^62 * 2 = 2^63 fits, but the next doubling (2^64) would overflow.
        let cfg = RetryConfig::new(6, 1u64 << 62, 1u64 << 63);
        let mut sleeper = FakeSleeper::default();
        let _ = run_job(&cfg, &mut sleeper, || Err(transient("always")));
        assert_eq!(
            sleeper.sleeps,
            vec![1u64 << 62, 1u64 << 63, 1u64 << 63, 1u64 << 63, 1u64 << 63]
        );
    }
}

//! Integration coverage for the public retry-policy contract.
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn transient(msg: &str) -> RetryError {
    RetryError::Transient(msg.to_string())
}

fn permanent(msg: &str) -> RetryError {
    RetryError::Permanent(msg.to_string())
}

#[test]
fn permanent_error_is_not_retried() {
    let cfg = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(permanent("bad input"))
    });
    assert_eq!(result, Err(permanent("bad input")));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_errors_are_retried_with_bounded_exponential_delay() {
    let cfg = RetryConfig {
        max_attempts: 6,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        if calls < 6 {
            Err(transient("blip"))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 6);
    assert_eq!(sleeper.sleeps, vec![10, 20, 40, 80, 100]);
}

#[test]
fn max_attempts_counts_the_first_call() {
    let cfg = RetryConfig::new(3, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(transient("always"))
    });
    assert_eq!(result, Err(transient("always")));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn saturation_above_safe_exponent_does_not_overflow() {
    let cfg = RetryConfig::new(5, 1u64 << 62, 1u64 << 63);
    let mut sleeper = FakeSleeper::default();
    let _ = run_job(&cfg, &mut sleeper, || Err(transient("always")));
    assert_eq!(
        sleeper.sleeps,
        vec![1u64 << 62, 1u64 << 63, 1u64 << 63, 1u64 << 63]
    );
}
